#[test]
fn test_is_local_energy_peak_true_peak() {
    let rir = vec![0.1f32, 0.5, 1.0, 0.5, 0.1];
    assert!(is_local_energy_peak(&rir, 2, 0, rir.len()));
}

#[test]
fn test_is_local_energy_peak_weak_right_strict_left() {
    // Equal right neighbour is still accepted as a peak if left is lower.
    let rir = vec![0.5f32, 1.0, 1.0, 0.5];
    assert!(is_local_energy_peak(&rir, 1, 0, rir.len()));
    assert!(!is_local_energy_peak(&rir, 2, 0, rir.len()));
}

#[test]
fn test_is_local_energy_peak_out_of_bounds() {
    let rir = vec![0.5f32];
    // A lone sample with no neighbours is treated as a peak.
    assert!(is_local_energy_peak(&rir, 0, 0, 1));
    assert!(!is_local_energy_peak(&rir, 5, 0, 1));
    assert!(!is_local_energy_peak(&rir, 0, 2, 1));
}

